{"command":"python3 << 'PY'
import subprocess, os, re, pty, fcntl, termios, struct
ansi=re.compile(br'\x1b\[[0-9;]*m')
def clean(b): return ansi.sub(b'',b).decode()
def run_pty(args, cols):
    master, slave = pty.openpty()
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH", 24, cols, 0,0))
    p=subprocess.Popen(["./executable"]+args, stdout=slave, stderr=slave, stdin=slave)
    os.close(slave); out=b""
    while True:
        try:
            d=os.read(master,8192)
            if not d: break
            out+=d
        except: break
    p.wait(); return out
for mode in [[],["--files"],["-l"]]:
    for cols in [40,80,90,100,120]:
        out=run_pty(mode+["/tmp/t1"] if "-l" not in mode else mode,cols)
        txt=clean(out.replace(b'\r\n',b'\n'))
        lines=txt.splitlines()
        print(mode, cols, [len(x) for x in lines[:2]])
PY"}

