    if len(x)==2 and x not in bc: bc.append(x)
block_candidates=bc

probes=[]  # list of (kind, token, content)
for t in line_candidates:
    probes.append(("line",t,f"{t} comment\nhello\n"))
for a,b in block_candidates:
    if b:
        probes.append(("block",(a,b),f"{a}\nhello\n{b}\nafter\n"))
    else:
        probes.append(("block",(a,b),f"{a}\nhello\n"))
# special plain cases
probes.append(("plain","hello","hello\nworld\n"))
probes.append(("plain","empty",""))

results={}
special_names={"Meson":"meson.build","NuGet Config":"nuget.config","Pacman's makepkg":"PKGBUILD","Scons":"SConstruct"}
