        filename=special_names[name]
        is_special=True
    elif exts_str=="<None>":
        continue
    else:
        ext=exts_str.split(",")[0].strip()
        filename=None
        is_special=False
    d="/tmp/tprobe_syn"; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    for pi,(kind,tok,content) in enumerate(probes):
        if is_special:
            sub=os.path.join(d,f"p{pi:03d}"); os.makedirs(sub); p=os.path.join(sub,filename)
        else:
            p=os.path.join(d,f"p{pi:03d}.{ext}")
        with open(p,"w",encoding="utf8") as f: f.write(content)
    r=subprocess.run([EXE,"-o","json",d],capture_output=True,text=True)
    try:
        jd=json.loads(r.stdout)
    except Exception as e:
        print("FAIL",name,e,r.stdout[:200],r.stderr[:200]); continue
    # map reports by basename dir/file
    byprobe={}
    detected=set()
    for lang, data in jd.items():
        if lang=="Total": continue
        detected.add(lang)
        for rep in data["reports"]:
            path=rep["name"]
            # probe index is pNNN component
            import re
            m=re.search(r'p(\d{3})',path)
            if m: byprobe[int(m.group(1))]=(lang,rep["stats"])
    rows=[]
    for pi,(kind,tok,content) in enumerate(probes):
        if pi in byprobe:
            lang,stats=byprobe[pi]
            rows.append([kind, tok if isinstance(tok,str) else list(tok), stats["code"],stats["comments"],stats["blanks"], list(stats["blobs"].keys())])
        else:
            rows.append([kind, tok if isinstance(tok,str) else list(tok), None,None,None,[]])
    results[name]={"detected":sorted(detected),"rows":rows}
    if idx%50==0: print("done",idx,name,detected, file=sys.stderr)
json.dump({"line_candidates":line_candidates,"block_candidates":block_candidates,"results":results},open("/tmp/probe_syn1.json","w"),ensure_ascii=False,indent=1)
print("saved")
