use std::collections::HashMap;
use std::path::Path;
use std::sync::OnceLock;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum QuoteKind {
    Normal,
    Verbatim,
}

#[derive(Clone, Copy, Debug)]
pub struct Quote {
    pub start: &'static str,
    pub end: &'static str,
    pub kind: QuoteKind,
}

#[derive(Clone, Copy, Debug)]
pub struct BlockComment {
    pub start: &'static str,
    pub end: &'static str,
    pub nested: bool,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum SpecKind {
    Normal,
    Fortran,
    Prose,
    Markdown,
    UnrealMarkdown,
    Jupyter,
}

#[derive(Debug)]
pub struct LanguageSpec {
    pub name: &'static str,
    pub extensions: &'static [&'static str],
    pub line_comments: &'static [&'static str],
    pub block_comments: &'static [BlockComment],
    pub quotes: &'static [Quote],
    pub kind: SpecKind,
}

include!("languages_data.rs");

impl LanguageType {
    pub fn spec(self) -> &'static LanguageSpec {
        &LANGUAGE_SPECS[self as usize]
    }
    pub fn name(self) -> &'static str {
        self.spec().name
    }
    pub fn all() -> impl Iterator<Item = LanguageType> {
        // LANGUAGE_SPECS and the enum are generated in the same order.
        (0..LANGUAGE_SPECS.len()).map(|i| unsafe { std::mem::transmute::<u32, LanguageType>(i as u32) })
    }
    pub fn from_display_name(name: &str) -> Option<Self> {
        LANGUAGE_SPECS
            .iter()
            .position(|s| s.name == name)
            .map(|i| Self::all().nth(i).unwrap())
    }
    /// The case-insensitive parsing used for --types and markdown fences.
    pub fn from_name_insensitive(name: &str) -> Option<Self> {
        LANGUAGE_SPECS
            .iter()
            .position(|s| s.name.to_lowercase() == name.to_lowercase())
            .map(|i| Self::all().nth(i).unwrap())
    }
}

impl std::fmt::Display for LanguageType {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(self.name())
    }
}

impl Serialize for LanguageType {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(self.name())
    }
}

impl<'de> Deserialize<'de> for LanguageType {
    fn deserialize<D: Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        let s = String::deserialize(deserializer)?;
        Self::from_display_name(&s)
            .ok_or_else(|| serde::de::Error::unknown_variant(&s, &[]))
    }
}

fn extension_map() -> &'static HashMap<String, LanguageType> {
    static MAP: OnceLock<HashMap<String, LanguageType>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
        for lang in LanguageType::all() {
            for ext in lang.spec().extensions {
                // The reference executable resolves the one duplicated
                // extension ("e") to Phix; keep the first entry for a key.
                m.entry(ext.to_lowercase()).or_insert(lang);
            }
        }
        m
    })
}

fn filename_map() -> &'static HashMap<&'static str, LanguageType> {
    static MAP: OnceLock<HashMap<&'static str, LanguageType>> = OnceLock::new();
    MAP.get_or_init(|| {
        let mut m = HashMap::new();
