        add("build", "Bazel");
        add("workspace", "Bazel");
        add("module", "Bazel");
        add("nuget.config", "NuGet Config");
        add("packages.config", "NuGet Config");
        add("snakefile", "Snakemake");
        m
    })
}

const DIRECT_SHEBANGS: &[(&str, &str)] = &[
    ("#!/bin/sh", "Shell"),
    ("#!/bin/bash", "BASH"),
    ("#!/bin/zsh", "Zsh"),
    ("#!/bin/fish", "Fish"),
    ("#!/bin/ksh", "Korn shell"),
    ("#!/bin/csh", "C Shell"),
    ("#!/usr/bin/perl", "Perl"),
    ("#!/usr/bin/raku", "Raku"),
    ("#!/usr/bin/perl6", "Raku"),
    ("#!/usr/bin/crystal", "Crystal"),
];

const ENV_SHEBANGS: &[(&str, &str)] = &[
    ("bash", "BASH"),
    ("csh", "C Shell"),
    ("crystal", "Crystal"),
    ("cython", "Cython"),
    ("elvish", "Elvish"),
    ("fish", "Fish"),
    ("groovy", "Groovy"),
    ("just", "Just"),
    ("ksh", "Korn shell"),
    ("perl6", "Raku"),
    ("python", "Python"),
    ("racket", "Racket"),
    ("raku", "Raku"),
    ("ruby", "Ruby"),
    ("sh", "Shell"),
];

fn from_shebang(path: &Path) -> Option<LanguageType> {
    use std::io::{BufRead, BufReader};
    let file = std::fs::File::open(path).ok()?;
    let mut reader = BufReader::new(file);
    let mut first = String::new();
    // BufReader::read_line returns an error on invalid UTF-8, matching the
    // behaviour of a read_line based implementation.
    if reader.read_line(&mut first).is_err() {
        return None;
    }
    from_shebang_line(&first)
}

pub fn from_shebang_line(first: &str) -> Option<LanguageType> {
    let mut parts = first.split_whitespace();
    let first_tok = parts.next()?;
    if first_tok == "#!/usr/bin/env" {
        if let Some(env) = parts.next() {
            for (name, display) in ENV_SHEBANGS {
                if env.starts_with(name) {
                    return LanguageType::from_display_name(display);
                }
            }
            log::warn!(target: "tokei::language::language_type", "Unknown environment: {:?}", env);
        }
        return None;
    }
    for (shebang, display) in DIRECT_SHEBANGS {
        if first_tok == *shebang {
            return LanguageType::from_display_name(display);
        }
    }
    None
}

impl LanguageType {
    pub fn from_path(path: &Path) -> Option<Self> {
        if let Some(file_name) = path.file_name().and_then(|s| s.to_str()) {
            if let Some(lang) = filename_map().get(file_name.to_lowercase().as_str()) {
                return Some(*lang);
            }
        }
        if let Some(ext) = path.extension() {
            // Rust's OsStr to_str is None for non-UTF8; the reference uses
            // to_string_lossy in some spots, but extension lookup on a
            // lossy string is close enough for non-UTF8 names and lets us
            // emit an unknown-extension warning like it does.
            let lower = ext.to_string_lossy().to_lowercase();
            if let Some(lang) = extension_map().get(&lower) {
                return Some(*lang);
            }
            log::warn!(target: "tokei::language::language_type", "Unknown extension: {}", lower);
            return None;
        }
        from_shebang(path)
    }
}
