    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub blobs: BTreeMap<LanguageType, CodeStats>,
}

impl CodeStats {
    pub fn new() -> Self { Self::default() }
    pub fn lines(&self) -> usize { self.blanks + self.code + self.comments }
    /// This stat line counts plus all blob lines recursively.
    pub fn total_lines(&self) -> usize {
        self.lines() + self.blobs.values().map(|b| b.total_lines()).sum::<usize>()
    }
    pub fn totals(&self) -> (usize, usize, usize) {
        let mut t = (self.blanks, self.code, self.comments);
        for b in self.blobs.values() {
            let bt = b.totals();
            t.0 += bt.0; t.1 += bt.1; t.2 += bt.2;
        }
        t
    }
    pub fn add(&mut self, other: &CodeStats) {
        self.blanks += other.blanks;
        self.code += other.code;
        self.comments += other.comments;
        for (lang, stats) in &other.blobs {
            let e = self.blobs.entry(*lang).or_default();
            e.add(stats);
        }
    }
    pub fn add_blob(&mut self, lang: LanguageType, stats: CodeStats) {
        let e = self.blobs.entry(lang).or_default();
        e.add(&stats);
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
pub struct Report {
    pub stats: CodeStats,
    pub name: PathBuf,
}

impl Report {
    pub fn new(name: PathBuf, stats: CodeStats) -> Self { Self { stats, name } }
}

#[derive(Clone, Debug, Default, Serialize, Deserialize)]
pub struct Language {
    pub blanks: usize,
    pub code: usize,
    pub comments: usize,
    pub reports: Vec<Report>,
    pub children: BTreeMap<LanguageType, Vec<Report>>,
    pub inaccurate: bool,
}

impl Language {
    pub fn new() -> Self { Self::default() }
    pub fn lines(&self) -> usize { self.blanks + self.code + self.comments }
    pub fn is_empty(&self) -> bool { self.reports.is_empty() }
    pub fn files(&self) -> usize { self.reports.len() }

    pub fn add_report(&mut self, report: Report) {
        self.blanks += report.stats.blanks;
        self.code += report.stats.code;
        self.comments += report.stats.comments;
        for (lang, blob) in &report.stats.blobs {
            self.children.entry(*lang).or_default().push(Report {
                stats: blob.clone(),
                name: report.name.clone(),
            });
        }
        self.reports.push(report);
    }

    /// Build a Language summarising a list of reports (used for children).
    pub fn summarise(reports: &[Report]) -> Language {
        let mut lang = Language::new();
        for r in reports {
            lang.add_report(r.clone());
        }
        lang
    }

    /// Recursive totals: (lines, code, comments, blanks)
    pub fn total(&self) -> (usize, usize, usize, usize) {
        let mut blanks = self.blanks;
        let mut code = self.code;
        let mut comments = self.comments;
        for reports in self.children.values() {
            let child = Self::summarise(reports);
            let (_, ccode, ccomments, cblanks) = child.total();
            code += ccode; comments += ccomments; blanks += cblanks;
        }
        (blanks + code + comments, code, comments, blanks)
    }
}

pub type Languages = BTreeMap<LanguageType, Language>;

/// Build the synthetic "Total" language used in JSON output.
pub fn build_total(languages: &Languages) -> Language {
    let mut total = Language::new();
    let mut blanks = 0usize; let mut code = 0usize; let mut comments = 0usize;
    for (lang_type, lang) in languages {
        let (_, c, com, b) = lang.total();
        code += c; comments += com; blanks += b;
        total.children.insert(*lang_type, lang.reports.clone());
        if lang.inaccurate { total.inaccurate = true; }
    }
    total.blanks = blanks; total.code = code; total.comments = comments;
    total
}
EOF"}

