use crate::language::{BlockComment, LanguageType, Quote, QuoteKind, SpecKind};
use crate::stats::CodeStats;

pub fn is_ws(b: u8) -> bool {
    matches!(b, b' ' | b'\t' | b'\r' | 0x0b | 0x0c)
}

fn char_len(text: &str, pos: usize) -> usize {
    text[pos..].chars().next().map(|c| c.len_utf8()).unwrap_or(1)
}

pub fn count_language(lang: LanguageType, text: &str) -> CodeStats {
    match lang.spec().kind {
        SpecKind::Jupyter => crate::jupyter::parse_jupyter(text),
        SpecKind::Markdown => parse_markdown(lang, text, false),
        SpecKind::UnrealMarkdown => parse_markdown(lang, text, true),
        SpecKind::Prose => parse_prose(text),
        SpecKind::Fortran => parse_fortran(lang, text),
        SpecKind::Normal => Scanner::new(lang, text).run(),
    }
}

fn parse_prose(text: &str) -> CodeStats {
    let mut stats = CodeStats::new();
    for line in text.lines() {
        if line.bytes().all(is_ws) {
            stats.blanks += 1;
        } else {
            stats.comments += 1;
        }
    }
    stats
}

fn parse_fortran(lang: LanguageType, text: &str) -> CodeStats {
    let mut stats = CodeStats::new();
    for line in text.lines() {
        if line.bytes().all(is_ws) {
            stats.blanks += 1;
        } else if lang
            .spec()
            .line_comments
            .iter()
            .any(|tok| line.starts_with(tok))
        {
            stats.comments += 1;
        } else {
            stats.code += 1;
        }
    }
    stats
}

#[derive(Clone, Copy)]
struct TagContext {
    tag: &'static str,
    child: LanguageType,
}

fn tag_contexts(lang: LanguageType) -> &'static [TagContext] {
    // The contexts lists are intentionally expanded at compile time via a
    // match rather than in the generated table.
    match lang {
        LanguageType::Html | LanguageType::RubyHtml | LanguageType::Svelte => &[
            TagContext { tag: "script", child: LanguageType::JavaScript },
            TagContext { tag: "style", child: LanguageType::Css },
        ],
        LanguageType::Vue => &[
            TagContext { tag: "script", child: LanguageType::JavaScript },
            TagContext { tag: "style", child: LanguageType::Css },
            TagContext { tag: "template", child: LanguageType::Html },
        ],
        LanguageType::GlimmerJs | LanguageType::GlimmerTs => &[
            TagContext { tag: "script", child: LanguageType::JavaScript },
            TagContext { tag: "style", child: LanguageType::Css },
            TagContext { tag: "template", child: LanguageType::Html },
        ],
        _ => &[],
    }
}

pub struct Scanner<'a> {
    lang: LanguageType,
    text: &'a str,
    bytes: &'a [u8],
    pos: usize,
    stats: CodeStats,
    comments: Vec<&'static BlockComment>,
    quote: Option<&'static Quote>,
    has_code: bool,
    has_comment: bool,
    has_line: bool,
}

impl<'a> Scanner<'a> {
    pub fn new(lang: LanguageType, text: &'a str) -> Self {
        Self {
            lang,
            text,
            bytes: text.as_bytes(),
            pos: 0,
            stats: CodeStats::new(),
            comments: Vec::new(),
            quote: None,
            has_code: false,
            has_comment: false,
            has_line: !text.is_empty(),
        }
    }

    fn starts_with(&self, s: &str) -> bool {
        self.text[self.pos..].starts_with(s)
    }

    fn classify_line(&mut self) {
        if !self.has_line {
            return;
        }
        if self.has_code {
            self.stats.code += 1;
        } else if self.has_comment {
            self.stats.comments += 1;
        } else {
            self.stats.blanks += 1;
        }
        self.has_code = false;
        self.has_comment = false;
        self.has_line = false;
    }

    fn begin_line(&mut self) {
        self.has_line = self.pos < self.bytes.len();
        if !self.comments.is_empty() {
            self.has_comment = true;
        }
        if self.quote.is_some() {
            self.has_code = true;
        }
    }

    fn line_end_from(&self, mut p: usize) -> usize {
        while p < self.bytes.len() && self.bytes[p] != b'\n' {
            p += 1;
        }
        p
    }

    /// Try an HTML-style tag context at the current position.  If a complete
    /// context is found it is consumed and Ok(true) is returned.
    fn try_tag_context(&mut self) -> bool {
        for ctx in tag_contexts(self.lang) {
            let open_prefix = format!("<{}", ctx.tag);
            if !self.starts_with(&open_prefix) {
                continue;
            }
            let after_name = self.pos + open_prefix.len();
            if after_name >= self.bytes.len() {
                continue;
            }
            let nb = self.bytes[after_name];
            if nb != b'>' && !matches!(nb, b' ' | b'\t' | b'\r' | 0x0b | 0x0c) {
                continue;
            }
            // Find '>' on the same physical line.
            let le = self.line_end_from(after_name);
            let mut gt = None;
            let mut i = after_name;
            while i < le {
                // Skip quoted attribute values for a '>' inside quotes.
                let c = self.bytes[i] as char;
                if c == '"' || c == '\'' {
                    i += 1;
                    while i < le && self.bytes[i] != c as u8 {
                        i += 1;
                    }
                } else if self.bytes[i] == b'>' {
                    gt = Some(i);
                    break;
                }
                i += 1;
            }
            let Some(gt) = gt else { continue };
            let close = format!("</{}>", ctx.tag);
            let content_after_gt = gt + 1;
            let Some(close_rel) = self.text[content_after_gt..].find(&close) else {
                continue;
            };
            let close_start = content_after_gt + close_rel;
            // Opening tag is part of the current (base) line.
            self.has_code = true;
            self.has_line = true;
            // The reference implementation skips one character after '>'
            // (intended to skip the newline, dropping a character of an
            // inline block).
            let mut content_start = content_after_gt;
            if content_start < close_start {
                content_start += char_len(self.text, content_start);
            }
            let captured = &self.text[content_start..close_start];
            let child_stats = count_language(ctx.child, captured);
            // Count the opening-tag line now.
            self.classify_line();
            if child_stats.code + child_stats.comments > 0 {
                self.stats.add_blob(ctx.child, child_stats);
            } else {
                // A wholly blank captured block contributes its blanks to
                // the outer language rather than creating a blob.
                self.stats.blanks += child_stats.blanks;
                // Preserve any nested blobs from a block whose direct
                // lines are blank (cannot normally happen).
                for (l, s) in child_stats.blobs {
                    self.stats.add_blob(l, s);
                }
            }
            self.pos = close_start;
            self.begin_line();
            return true;
        }
        false
    }

    /// Rust /// and //! doc comments. Returns true if consumed.
    fn try_rust_doc(&mut self) -> bool {
        if self.lang != LanguageType::Rust {
            return false;
        }
        let tok = if self.starts_with("///") {
            "///"
        } else if self.starts_with("//!") {
            "//!"
        } else {
            return false;
        };
        // Collect this line's contents after the token.
        let mut contents: Vec<&str> = Vec::new();
        let le = self.line_end_from(self.pos);
        contents.push(&self.text[self.pos + tok.len()..le]);
        let mut cursor = if le < self.bytes.len() { le + 1 } else { le };
        // Collect subsequent doc lines, discarding blank lines that are
        // followed by another doc line.
        loop {
            if cursor >= self.bytes.len() {
                break;
            }
            let lend = self.line_end_from(cursor);
            let raw_line = &self.text[cursor..lend];
            let trimmed = raw_line.trim_start_matches(|c: char| matches!(c, ' ' | '\t' | '\r' | '\x0b' | '\x0c'));
            if let Some(rest) = trimmed.strip_prefix("///").or_else(|| trimmed.strip_prefix("//!")) {
                contents.push(rest);
                cursor = if lend < self.bytes.len() { lend + 1 } else { lend };
                continue;
            }
            if raw_line.bytes().all(is_ws) {
                // Peek through all consecutive blank lines.
                let mut peek = if lend < self.bytes.len() { lend + 1 } else { lend };
                let mut found_doc = false;
                while peek < self.bytes.len() {
                    let pend = self.line_end_from(peek);
                    let pline = &self.text[peek..pend];
                    let ptr = pline.trim_start_matches(|c: char| matches!(c, ' ' | '\t' | '\r' | '\x0b' | '\x0c'));
                    if ptr.starts_with("///") || ptr.starts_with("//!") {
                        found_doc = true;
                        break;
                    }
                    if !pline.bytes().all(is_ws) {
                        break;
                    }
                    peek = if pend < self.bytes.len() { pend + 1 } else { pend };
                }
                if found_doc {
                    cursor = peek;
                    continue;
                }
            }
            break;
        }
        let mut md = String::new();
        for c in &contents {
            md.push_str(c);
            md.push('\n');
        }
        let md_stats = count_language(LanguageType::Markdown, &md);
        // The line containing the first doc token is not counted in Rust.
        self.has_code = false;
        self.has_comment = false;
        self.has_line = false;
        self.stats.add_blob(LanguageType::Markdown, md_stats);
        self.pos = cursor;
        self.begin_line();
        true
    }

    pub fn run(mut self) -> CodeStats {
        let spec = self.lang.spec();
        while self.pos < self.bytes.len() {
            let b = self.bytes[self.pos];
            if b == b'\n' {
                self.pos += 1;
                self.classify_line();
                self.begin_line();
                continue;
            }

            if let Some(q) = self.quote {
                self.has_code = true;
                self.has_line = true;
                if q.kind == QuoteKind::Normal && b == b'\\' {
                    self.pos += 1;
                    if self.pos < self.bytes.len() && self.bytes[self.pos] != b'\n' {
                        self.pos += char_len(self.text, self.pos);
                    }
                    continue;
                }
                if self.starts_with(q.end) {
                    self.pos += q.end.len();
                    self.quote = None;
                    continue;
                }
                self.pos += char_len(self.text, self.pos);
                continue;
            }

            if let Some(top) = self.comments.last().copied() {
                self.has_comment = true;
                self.has_line = true;
                if self.starts_with(top.end) {
                    self.pos += top.end.len();
                    self.comments.pop();
                    continue;
                }
                if top.nested && self.starts_with(top.start) {
                    self.pos += top.start.len();
                    self.comments.push(top);
                    continue;
                }
                self.pos += char_len(self.text, self.pos);
                continue;
            }

            // Embedded contexts are checked before normal tokens.
            if self.try_rust_doc() {
                continue;
            }
            if self.try_tag_context() {
                continue;
            }

            // Find longest matching token at this position.
            let mut best_len = 0usize;
            let mut line_tok: Option<&'static str> = None;
            let mut block_tok: Option<&'static BlockComment> = None;
            let mut quote_tok: Option<&'static Quote> = None;
            for t in spec.line_comments {
                if t.len() > best_len && self.starts_with(t) {
                    best_len = t.len();
                    line_tok = Some(t);
                    block_tok = None;
                    quote_tok = None;
                }
            }
            for bc in spec.block_comments {
                if bc.start.len() >= best_len && self.starts_with(bc.start) {
                    // Prefer blocks on a tie (e.g. {{! in Dust).
                    if bc.start.len() > best_len || block_tok.is_some() || line_tok.is_some() {
                        best_len = bc.start.len();
                        block_tok = Some(bc);
                        line_tok = None;
                        quote_tok = None;
                    }
                }
            }
            for q in spec.quotes {
                if q.start.len() > best_len && self.starts_with(q.start) {
                    best_len = q.start.len();
                    quote_tok = Some(q);
                    line_tok = None;
                    block_tok = None;
                }
            }

            if let Some(t) = line_tok {
                self.has_comment = true;
                self.has_line = true;
                self.pos = self.line_end_from(self.pos + t.len());
                continue;
            }
            if let Some(bc) = block_tok {
                self.has_comment = true;
                self.has_line = true;
                self.pos += bc.start.len();
                self.comments.push(bc);
                continue;
            }
            if let Some(q) = quote_tok {
                self.has_code = true;
                self.has_line = true;
                self.pos += q.start.len();
                self.quote = Some(q);
                continue;
            }

            if is_ws(b) {
                self.pos += 1;
            } else {
                self.has_code = true;
                self.has_line = true;
                self.pos += char_len(self.text, self.pos);
            }
        }
        self.classify_line();
        self.stats
    }
}

fn parse_markdown(lang: LanguageType, text: &str, unreal: bool) -> CodeStats {
    // Markdown (and Unreal Markdown) are processed line-oriented, except
    // that ``` fences can start/end in the middle of a physical line and
    // create extra logical lines, as in the reference.
    let mut stats = CodeStats::new();
    let bytes = text.as_bytes();
