                None => (segment, None),
            };
            let lang_name = token.split(',').next().unwrap_or("");
            if let Some(child) = LanguageType::from_name_insensitive(lang_name) {
                // Count the opening logical line as a comment (for Unreal
                // as well as Markdown).
                if has_line {
                    stats.comments += 1;
                }
                let block_raw = match rest_start_rel {
