                    let le = {
                        let mut p = pos;
                        while p < bytes.len() && bytes[p] != b'\n' { p += 1; }
                        p
                    };
                    let remainder = &text[pos..le];
                    if remainder.is_empty() {
                        // Consume the newline if present; move to next line.
                        if le < bytes.len() {
                            pos = le + 1;
                        } else {
                            pos = le;
                        }
                        has_nonws = false;
                        has_line = pos < bytes.len();
                    } else if remainder.bytes().all(is_ws) && le >= bytes.len() {
                        // Trailing whitespace at EOF after a closing fence
                        // does not make another line.
                        pos = le;
                        has_line = false;
                        has_nonws = false;
                    } else {
                        has_nonws = false;
                        has_line = true;
                    }
                } else {
                    pos = bytes.len();
                    has_line = false;
                }
                continue;
            }
            // Unknown language: the fence is ordinary (comment/code) text.
            has_nonws = true;
            has_line = true;
            pos += 3;
            continue;
        }
        if !is_ws(bytes[pos]) {
            has_nonws = true;
        }
        has_line = true;
        pos += char_len(text, pos);
    }
    if has_line {
        classify(&mut stats, has_nonws, unreal);
    }
    let _ = lang;
    stats
}
