#[derive(Debug)]
pub struct DecString(&'static str);
#[derive(Debug)]
pub enum Grouping {
    Standard,
}
#[derive(Debug)]
pub struct InfString(&'static str);
#[derive(Debug)]
pub struct MinString(&'static str);
#[derive(Debug)]
pub struct NanString(&'static str);
#[derive(Debug)]
pub struct PlusString(&'static str);
#[derive(Debug)]
pub struct SepString(&'static str);

#[derive(Debug)]
pub struct CustomFormat {
    dec: DecString,
    grp: Grouping,
    inf: InfString,
    min: MinString,
    nan: NanString,
    plus: PlusString,
    sep: SepString,
}

impl CustomFormat {
    pub fn from_style(style: Option<&str>) -> Self {
        let sep = match style {
            Some("commas") => ",",
            Some("dots") => ".",
            Some("underscores") => "_",
            _ => "",
        };
        Self {
            dec: DecString("."),
            grp: Grouping::Standard,
            inf: InfString("∞"),
            min: MinString("-"),
            nan: NanString("NaN"),
            plus: PlusString("+"),
            sep: SepString(sep),
        }
    }
    pub fn format(&self, n: usize) -> String {
        let sep = self.sep.0;
        if sep.is_empty() {
            return n.to_string();
        }
        let s = n.to_string();
        let bytes = s.as_bytes();
        let mut out = String::new();
        for (i, ch) in s.chars().enumerate() {
            if i > 0 && (bytes.len() - i) % 3 == 0 {
                out.push_str(sep);
            }
            out.push(ch);
        }
        out
    }
}

