        .arg(
            Arg::new("sort")
                .short('s')
                .long("sort")
                .value_name("sort")
                .help("Sort languages based on column")
                .value_parser(["files", "lines", "blanks", "code", "comments"])
                .ignore_case(true)
                .conflicts_with("rsort"),
        )
        .arg(
            Arg::new("rsort")
                .short('r')
                .long("rsort")
                .value_name("rsort")
                .help("Reverse sort languages based on column")
                .value_parser(["files", "lines", "blanks", "code", "comments"])
                .ignore_case(true),
        )
        .arg(
            Arg::new("types")
                .short('t')
                .long("types")
                .value_name("types")
                .help("Filters output by language type, separated by a comma. i.e. -t=Rust,Markdown")
                .value_parser(clap::value_parser!(String))
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("compact")
                .short('C')
                .long("compact")
                .help("Do not print statistics about embedded languages.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("num_format_style")
                .short('n')
                .long("num-format")
                .value_name("num_format_style")
                .help("Format of printed numbers, i.e., plain (1234, default), commas (1,234), dots (1.234), or underscores (1_234). Cannot be used with --output.")
                .value_parser(["commas", "dots", "plain", "underscores"])
                .conflicts_with("output"),
        )
        .arg(
            Arg::new("verbose")
                .short('v')
                .long("verbose")
                .help("Set log output level:\n1: to show unknown file extensions,\n2: reserved for future debugging,\n3: enable file level trace. Not\nrecommended on multiple files")
                .action(ArgAction::Count),
        )
        .arg(
            Arg::new("input")
                .help("The path(s) to the file or directory to be counted. (default current directory)")
                .value_name("input")
                .value_parser(clap::value_parser!(String))
                .action(ArgAction::Append)
                .num_args(0..),
        )
}

fn sort_from(s: &str) -> Sort {
    match s.to_lowercase().as_str() {
        "files" => Sort::Files,
        "lines" => Sort::Lines,
        "blanks" => Sort::Blanks,
        "comments" => Sort::Comments,
        _ => Sort::Code,
    }
}

impl Cli {
    pub fn from_matches(matches: ArgMatches) -> Self {
        let columns = matches.get_one::<usize>("columns").copied();
        let files = matches.get_flag("files");
        let hidden = matches.get_flag("hidden");
        let no_ignore = matches.get_flag("no_ignore");
        let no_ignore_parent = matches.get_flag("no_ignore_parent");
        let no_ignore_dot = matches.get_flag("no_ignore_dot");
        let no_ignore_vcs = matches.get_flag("no_ignore_vcs");
        let output = matches.get_one::<OutputFormat>("output").copied();
        let streaming = matches.get_one::<String>("streaming").map(|s| {
            if s.eq_ignore_ascii_case("json") { Streaming::Json } else { Streaming::Simple }
        });
        let print_languages = matches.get_flag("languages");
        let (sort, sort_reverse) = if let Some(s) = matches.get_one::<String>("sort") {
            (Some(sort_from(s)), false)
        } else if let Some(s) = matches.get_one::<String>("rsort") {
            (Some(sort_from(s)), true)
        } else {
            (None, false)
        };
        let types = matches.get_many::<String>("types").map(|vals| {
            vals.flat_map(|v| v.split(','))
                .filter_map(|t| LanguageType::from_name_insensitive(t))
                .collect::<Vec<_>>()
        });
        let compact = matches.get_flag("compact");
        let number_format = CustomFormat::from_style(matches.get_one::<String>("num_format_style").map(|s| s.as_str()));
        Self {
            matches,
            columns,
            files,
            hidden,
            no_ignore,
            no_ignore_parent,
            no_ignore_dot,
            no_ignore_vcs,
            output,
            streaming,
            print_languages,
            sort,
            sort_reverse,
            types,
            compact,
            number_format,
        }
    }

    pub fn verbose(&self) -> u8 {
        self.matches.get_count("verbose")
    }
    pub fn inputs(&self) -> Vec<String> {
        match self.matches.get_many::<String>("input") {
            Some(vals) => vals.cloned().collect(),
            None => vec![".".to_owned()],
        }
    }
    pub fn file_input(&self) -> Option<&String> {
        self.matches.get_one::<String>("file_input")
    }
    pub fn exclude(&self) -> Vec<String> {
        match self.matches.get_many::<String>("exclude") {
            Some(vals) => vals.cloned().collect(),
            None => Vec::new(),
        }
    }
}
EOF"}

