use crate::language::LanguageType;
use crate::stats::CodeStats;
use crate::syntax::count_language;
use serde_json::Value;

fn source_text(v: &Value) -> Option<String> {
    match v {
        Value::String(s) => Some(s.clone()),
        Value::Array(items) => {
            let mut out = String::new();
            for it in items {
                out.push_str(it.as_str()?);
            }
            Some(out)
        }
        _ => None,
    }
}

fn notebook_language(nb: &Value, cell: &Value) -> Option<LanguageType> {
    // Per-cell VS Code language id takes precedence if present.
    if let Some(id) = cell
        .pointer("/metadata/vscode/languageId")
        .and_then(|v| v.as_str())
    {
        if let Some(l) = LanguageType::from_name_insensitive(id) {
            return Some(l);
        }
    }
    if let Some(name) = nb.pointer("/metadata/language_info/name").and_then(|v| v.as_str()) {
        if let Some(l) = LanguageType::from_name_insensitive(name) {
            return Some(l);
        }
    }
    if let Some(name) = nb.pointer("/metadata/kernelspec/language").and_then(|v| v.as_str()) {
        if let Some(l) = LanguageType::from_name_insensitive(name) {
            return Some(l);
        }
    }
    if let Some(name) = nb.pointer("/metadata/kernelspec/name").and_then(|v| v.as_str()) {
        let cleaned: String = name.chars().take_while(|c| c.is_ascii_alphabetic()).collect();
        if let Some(l) = LanguageType::from_name_insensitive(&cleaned) {
            return Some(l);
        }
    }
    LanguageType::from_display_name("Python")
}

pub fn parse_jupyter(text: &str) -> CodeStats {
    let mut stats = CodeStats::new();
    let Ok(nb) = serde_json::from_str::<Value>(text) else {
        return stats;
    };
    let Some(cells) = nb.get("cells").and_then(|c| c.as_array()) else {
        return stats;
    };
    // Validate and collect first: an unsupported cell type (e.g. "raw")
    // makes the whole notebook yield zero statistics.
    enum CellKind { Code, Markdown }
    let mut parsed: Vec<(CellKind, LanguageType, String)> = Vec::new();
    for cell in cells {
        let Some(cell_type) = cell.get("cell_type").and_then(|v| v.as_str()) else {
            return CodeStats::new();
        };
        let Some(src_value) = cell.get("source") else {
            return CodeStats::new();
        };
        let Some(source) = source_text(src_value) else {
            return CodeStats::new();
        };
        match cell_type {
            "code" => {
                let Some(lang) = notebook_language(&nb, cell) else {
                    return CodeStats::new();
                };
                parsed.push((CellKind::Code, lang, source));
            }
            "markdown" => {
                parsed.push((CellKind::Markdown, LanguageType::Markdown, source));
            }
            _ => return CodeStats::new(),
        }
    }
    for (_, lang, source) in parsed {
        let cell_stats = count_language(lang, &source);
        stats.blanks += cell_stats.blanks;
        stats.code += cell_stats.code;
        stats.comments += cell_stats.comments;
        stats.add_blob(lang, cell_stats);
    }
    stats
}
EOF"}

