{"command":"cat > src/fs_walk.rs <<'EOF'
use crate::cli::{Cli, Streaming};
use crate::language::LanguageType;
use crate::stats::{CodeStats, Languages, Report};
use crate::syntax::count_language;
use ignore::overrides::OverrideBuilder;
use ignore::{WalkBuilder, WalkState};
use std::collections::HashSet;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::sync::mpsc;

pub fn decode_bytes(bytes: &[u8]) -> String {
    if bytes.starts_with(&[0xFF, 0xFE]) {
        let units: Vec<u16> = bytes[2..]
            .chunks_exact(2)
            .map(|c| u16::from_le_bytes([c[0], c[1]]))
            .collect();
        let mut s: String = char::decode_utf16(units.into_iter())
            .map(|r| r.unwrap_or(char::REPLACEMENT_CHARACTER))
            .collect();
        if bytes.len() % 2 == 1 {
            s.push(char::REPLACEMENT_CHARACTER);
        }
        return s;
    }
    if bytes.starts_with(&[0xFE, 0xFF]) {
        let units: Vec<u16> = bytes[2..]
            .chunks_exact(2)
            .map(|c| u16::from_be_bytes([c[0], c[1]]))
            .collect();
        let mut s: String = char::decode_utf16(units.into_iter())
            .map(|r| r.unwrap_or(char::REPLACEMENT_CHARACTER))
            .collect();
        if bytes.len() % 2 == 1 {
            s.push(char::REPLACEMENT_CHARACTER);
        }
        return s;
    }
    if bytes.starts_with(&[0xEF, 0xBB, 0xBF]) {
        return String::from_utf8_lossy(&bytes[3..]).into_owned();
    }
    String::from_utf8_lossy(bytes).into_owned()
}

pub enum Event {
    Report(LanguageType, Report),
    Inaccurate(LanguageType),
}

fn process_path(
    path: &Path,
    types: &Option<HashSet<LanguageType>>,
    tx: &mpsc::Sender<Event>,
    streaming: Option<Streaming>,
) {
    let Some(lang) = LanguageType::from_path(path) else {
        return;
    };
    if let Some(set) = types {
        if !set.contains(&lang) {
            return;
        }
    }
    match std::fs::read(path) {
        Ok(bytes) => {
            // -vvv file-level trace is handled inside the language
            // parsers in the reference; we emit a minimal trace of each
            // line for language_type which matches simple cases.
            let text = decode_bytes(&bytes);
            let stats = count_language(lang, &text);
            let report = Report::new(path.to_path_buf(), stats);
            if let Some(mode) = streaming {
                print_streaming(mode, lang, &report);
            }
            let _ = tx.send(Event::Report(lang, report));
        }
        Err(e) => {
            log::error!(target: "tokei::utils::fs", "Error reading {}:\n    {}", path.display(), e);
            let _ = tx.send(Event::Inaccurate(lang));
        }
    }
}

pub fn print_streaming(mode: Streaming, lang: LanguageType, report: &Report) {
    match mode {
        Streaming::Simple => {
            // `println!` is used deliberately: it matches the reference's
            // broken-pipe behaviour for streaming output.
            println!(
                "{:>10} {:<80} {:>12} {:>12} {:>12} {:>12}",
                lang.name(),
                report.name.display(),
                report.stats.lines(),
                report.stats.code,
                report.stats.comments,
                report.stats.blanks
            );
        }
        Streaming::Json => {
            #[derive(serde::Serialize)]
            struct Record {
                language: LanguageType,
                stats: Report,
            }
            let record = Record { language: lang, stats: report.clone() };
            // Converting through a Value gives alphabetically sorted keys.
            if let Ok(value) = serde_json::to_value(&record) {
                println!("{}", value);
            }
            let _ = std::io::stdout().flush();
        }
    }
}

fn build_overrides(cli: &Cli) -> Option<ignore::overrides::Override> {
    let patterns = cli.exclude();
    if patterns.is_empty() {
        return None;
    }
    let mut builder = OverrideBuilder::new(".");
    for pat in &patterns {
        let glob = format!("!{pat}");
        if let Err(e) = builder.add(&glob) {
            log::error!(target: "tokei::utils::fs", "error parsing glob '{glob}': {e}");
        }
    }
    match builder.build() {
        Ok(o) => Some(o),
        Err(e) => {
            log::error!(target: "tokei::utils::fs", "{e}");
            None
        }
    }
}

pub fn get_statistics(
    inputs: &[PathBuf],
    cli: &Cli,
    streaming: Option<Streaming>,
) -> Languages {
    let types: Option<HashSet<LanguageType>> = cli
        .types
        .as_ref()
        .map(|v| v.iter().copied().collect());
    let overrides = build_overrides(cli);
    let (tx, rx) = mpsc::channel::<Event>();

    for input in inputs {
        if input.is_file() {
            process_path(input, &types, &tx, streaming);
            continue;
        }
        if !input.is_dir() {
            continue;
        }
        let mut builder = WalkBuilder::new(input);
        let no_parent = cli.no_ignore || cli.no_ignore_parent;
        let no_dot = cli.no_ignore || cli.no_ignore_dot;
        let no_vcs = cli.no_ignore || cli.no_ignore_vcs;
        builder
            .hidden(!cli.hidden)
            .ignore(!no_dot)
            .parents(!no_parent)
            .git_ignore(!no_vcs)
            .git_global(!no_vcs)
            .git_exclude(!no_vcs)
            .require_git(true)
            .follow_links(false);
        builder.add_custom_ignore_filename(".tokeignore");
        if let Some(ov) = &overrides {
            builder.overrides(ov.clone());
        }
        let walker = builder.build_parallel();
        let tx2 = tx.clone();
        let types2 = types.clone();
        walker.run(|| {
            let tx = tx2.clone();
            let types = types2.clone();
            Box::new(move |result| {
                match result {
                    Ok(entry) => {
                        let is_file = entry.file_type().map(|ft| ft.is_file()).unwrap_or(false);
                        if is_file {
                            process_path(entry.path(), &types, &tx, streaming);
                        }
                    }
                    Err(e) => {
                        log::error!(target: "tokei::utils::fs", "{}", e);
                    }
                }
                WalkState::Continue
            })
        });
    }
    drop(tx);
    let mut languages: Languages = Languages::new();
    for event in rx {
        match event {
            Event::Report(lang, report) => {
                languages.entry(lang).or_default().add_report(report);
            }
            Event::Inaccurate(lang) => {
                languages.entry(lang).or_default().inaccurate = true;
            }
        }
    }
    languages
}
EOF"}

