            true,
        )
    )?;
    writeln!(out, "{heavy}")?;
    out.flush()
}

// ---------- print languages (-l) ----------

fn truncate_cell(content: &str, width: usize) -> String {
    let count = content.chars().count();
    if count <= width {
        return content.to_string();
    }
    if width >= 3 {
        let mut s: String = content.chars().take(width - 3).collect();
        s.push_str("...");
        s
    } else if width == 2 {
        let mut s: String = content.chars().take(1).collect();
        s.push('.');
        s
    } else if width == 1 {
        ".".to_string()
    } else {
        String::new()
    }
}

fn pad_cell(content: &str, width: usize) -> String {
    let truncated = truncate_cell(content, width);
    let c = truncated.chars().count();
    let mut out = truncated;
    if c < width {
        out.push_str(&" ".repeat(width - c));
    }
    out
}

pub fn print_languages() -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let term = terminal_width();
    let (cell1, cell2) = match term {
        Some(t) if t > 0 => {
            if t <= 88 {
                let cell = t.saturating_sub(4) / 2;
                (cell, cell)
            } else {
                (42, t - 46)
            }
        }
        _ => (35, 35),
    };
    let total = cell1 + cell2 + 2;
    let border = "┃".bold().to_string();
    let make_cell1 = |content: &str| -> String { format!(" {} ", pad_cell(content, cell1 - 2)) };
    let make_cell2 = |content: &str| -> String { format!("    {} ", pad_cell(content, cell2 - 5)) };

    writeln!(out, "{}", "━".repeat(total).bold())?;
    writeln!(
        out,
        "{}{}{}{}",
        border,
        make_cell1("Language").bold(),
        make_cell2("Extensions").bold(),
        border
    )?;
    writeln!(
        out,
        "{}{}{}{}",
        border,
        "━".repeat(cell1).bold(),
        "━".repeat(cell2).bold(),
        border
    )?;
    for lang in LanguageType::all() {
        let spec = lang.spec();
        let exts = if spec.extensions.is_empty() {
            "<None>".to_string()
        } else {
            spec.extensions.join(", ")
        };
        writeln!(out, "{}{}{}{}", border, make_cell1(spec.name), make_cell2(&exts), border)?;
    }
    writeln!(out, "{}", "━".repeat(total).bold())?;
    writeln!(out)?;
    out.flush()
}
