use crate::cli::{Cli, Sort};
use crate::language::LanguageType;
use crate::stats::{build_total, CodeStats, Language, Languages, Report};
use colored::Colorize;
use serde::ser::{SerializeMap, Serializer};
use std::io::{self, Write};

pub fn terminal_width() -> Option<usize> {
    // Check stdout, then stdin, then stderr (matching the reference).
    for fd in [1i32, 0, 2] {
        let mut winsz: libc::winsize = unsafe { std::mem::zeroed() };
        let ret = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsz) };
        if ret == 0 && winsz.ws_col > 0 {
            return Some(winsz.ws_col as usize);
        }
    }
    None
}

struct JsonLanguages<'a>(&'a Languages);
impl serde::Serialize for JsonLanguages<'_> {
    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        let total = build_total(self.0);
        let mut map = serializer.serialize_map(Some(self.0.len() + 1))?;
        for (k, v) in self.0 {
            map.serialize_entry(&k.name(), v)?;
        }
        map.serialize_entry("Total", &total)?;
        map.end()
    }
}

pub fn print_json(languages: &Languages) {
    let s = serde_json::to_string(&JsonLanguages(languages)).unwrap();
    print!("{s}");
    let _ = io::stdout().flush();
}

fn truncate_right(s: &str, width: usize) -> String {
    let count = s.chars().count();
    if count <= width {
        let mut out = s.to_string();
        out.push_str(&" ".repeat(width - count));
        out
    } else if width == 0 {
        String::new()
    } else {
        let mut out: String = s.chars().take(width - 1).collect();
        out.push('|');
        out
    }
}

fn truncate_path_left(s: &str, width: usize) -> String {
    let count = s.chars().count();
    if count <= width {
        let mut out = s.to_string();
        out.push_str(&" ".repeat(width - count));
        out
    } else if width == 0 {
        String::new()
    } else {
        let skip = count - (width - 1);
        let mut out = String::from("|");
        out.extend(s.chars().skip(skip));
        out
    }
}

fn name_segment(name: &str, width: usize, inaccurate: bool) -> (String, &'static str) {
    if inaccurate {
        let w = width.saturating_sub(3);
        (truncate_right(name, w), "(!)")
    } else {
        (truncate_right(name, width), "")
    }
}

fn summary_row(
    name: &str,
    name_width: usize,
    files: Option<usize>,
    lines: usize,
    code: usize,
    comments: usize,
    blanks: usize,
    cli: &Cli,
    inaccurate: bool,
    color_name: bool,
    total_colors: bool,
) -> String {
    let (padded, marker) = name_segment(name, name_width, inaccurate);
    let name_disp = if color_name {
        format!("{}", padded.purple().bold())
    } else {
        padded
    };
    let f = &cli.number_format;
    let files_s = match files {
        Some(n) => f.format(n),
        None => String::new(),
    };
    if total_colors {
        let files_disp = format!("{:>8}", files_s).blue().to_string();
        let lines_disp = format!("{:>12}", f.format(lines)).blue().to_string();
        let code_disp = format!("{:>12}", f.format(code)).blue().to_string();
        let com_disp = format!("{:>12}", f.format(comments)).blue().to_string();
        let blank_disp = format!("{:>12}", f.format(blanks)).blue().to_string();
        format!(" {name_disp}{marker} {files_disp} {lines_disp} {code_disp} {com_disp} {blank_disp}")
    } else {
        format!(
            " {name_disp}{marker} {:>8} {:>12} {:>12} {:>12} {:>12}",
            files_s,
            f.format(lines),
            f.format(code),
            f.format(comments),
            f.format(blanks)
        )
    }
}

fn child_row(
    name: &str,
    name_width: usize,
    files: Option<usize>,
    lines: usize,
    code: usize,
    comments: usize,
    blanks: usize,
    cli: &Cli,
) -> String {
    let w = name_width.saturating_sub(3);
    let padded = truncate_right(name, w);
    let name_disp = format!("{}", padded.purple().bold());
    let f = &cli.number_format;
    let files_s = match files {
        Some(n) => f.format(n),
        None => String::new(),
    };
    format!(
        " |- {name_disp} {:>8} {:>12} {:>12} {:>12} {:>12}",
        files_s,
        f.format(lines),
        f.format(code),
        f.format(comments),
        f.format(blanks)
    )
}

fn report_row_plain(name: &str, name_width: usize, stats: &CodeStats) -> String {
    let field = name_width + 9;
    let padded = truncate_path_left(name, field);
    format!(
        " {} {:>12} {:>12} {:>12} {:>12}",
        padded,
        stats.lines(),
        stats.code,
        stats.comments,
        stats.blanks
    )
}

fn sorted_language_entries<'a>(
    languages: &'a Languages,
    cli: &Cli,
) -> Vec<(LanguageType, &'a Language)> {
    let mut v: Vec<(LanguageType, &Language)> = languages
        .iter()
        .filter(|(_, l)| !l.is_empty())
        .map(|(k, v)| (*k, v))
        .collect();
    if let Some(sort) = cli.sort {
        v.sort_by(|a, b| {
            let ka = match sort {
                Sort::Files => a.1.files(),
                Sort::Lines => a.1.lines(),
                Sort::Blanks => a.1.blanks,
                Sort::Code => a.1.code,
                Sort::Comments => a.1.comments,
            };
            let kb = match sort {
                Sort::Files => b.1.files(),
                Sort::Lines => b.1.lines(),
                Sort::Blanks => b.1.blanks,
                Sort::Code => b.1.code,
                Sort::Comments => b.1.comments,
            };
            kb.cmp(&ka)
        });
        if cli.sort_reverse {
            v.reverse();
        }
    }
    v
}

