        let lines_seg = format!("{:>12}", "Lines").blue().bold().to_string();
        let code_seg = format!("{:>12}", "Code").blue().bold().to_string();
        let com_seg = format!("{:>12}", "Comments").blue().bold().to_string();
        let blank_seg = format!("{:>12}", "Blanks").blue().bold().to_string();
        writeln!(out, " {lang_seg} {files_seg} {lines_seg} {code_seg} {com_seg} {blank_seg}")?;
    }
    writeln!(out, "{heavy}")?;

    let entries = sorted_language_entries(languages, cli);
    let total_lang = build_total(languages);

    for (idx, (lang_type, lang)) in entries.iter().enumerate() {
