                            out,
                            "{}",
                            child_row(
                                blob_lang.name(),
                                name_width,
                                None,
                                blob_stats.lines(),
                                blob_stats.code,
                                blob_stats.comments,
                                blob_stats.blanks,
                                cli,
                            )
                        )?;
                    }
                    // Final line for this report, summary format without
                    // truncating the path.
                    writeln!(
                        out,
                        "{}",
                        summary_row(
                            &report.name.display().to_string(),
                            name_width,
                            None,
                            report.stats.lines(),
                            report.stats.code,
                            report.stats.comments,
                            report.stats.blanks,
                            cli,
                            false,
                            false,
                            false,
                        )
                    )?;
                }
            }
            if !is_last {
                writeln!(out, "{light_dim}")?;
            }
        } else if show_children && !is_last {
            writeln!(out, "{light_dim}")?;
        }
    }

    writeln!(out, "{heavy}")?;
    let total_files: usize = languages.values().map(|l| l.files()).sum();
    writeln!(
        out,
        "{}",
        summary_row(
            "Total",
            name_width,
            Some(total_files),
            total_lang.lines(),
            total_lang.code,
            total_lang.comments,
            total_lang.blanks,
            cli,
            total_lang.inaccurate,
            true,
            true,
        )
    )?;
    writeln!(out, "{heavy}")?;
