fn summary_row(
    name: &str,
    name_width: usize,
    files: Option<usize>,
    lines: usize,
    code: usize,
    comments: usize,
    blanks: usize,
    cli: &Cli,
    inaccurate: bool,
    color_name: bool,
    total_colors: bool,
) -> String {
    let (padded, marker) = name_segment(name, name_width, inaccurate);
    let name_disp = if color_name {
        format!("{}", padded.purple().bold())
    } else {
        padded
    };
    let f = &cli.number_format;
    let files_s = match files {
        Some(n) => f.format(n),
        None => String::new(),
    };
    if total_colors {
        let files_disp = format!("{:>8}", files_s).blue().to_string();
        let lines_disp = format!("{:>12}", f.format(lines)).blue().to_string();
        let code_disp = format!("{:>12}", f.format(code)).blue().to_string();
        let com_disp = format!("{:>12}", f.format(comments)).blue().to_string();
        let blank_disp = format!("{:>12}", f.format(blanks)).blue().to_string();
        format!(" {name_disp}{marker} {files_disp} {lines_disp} {code_disp} {com_disp} {blank_disp}")
    } else {
        format!(
            " {name_disp}{marker} {:>8} {:>12} {:>12} {:>12} {:>12}",
            files_s,
            f.format(lines),
            f.format(code),
            f.format(comments),
            f.format(blanks)
        )
    }
}

fn child_row(
    name: &str,
    name_width: usize,
    files: Option<usize>,
    lines: usize,
    code: usize,
    comments: usize,
    blanks: usize,
    cli: &Cli,
) -> String {
    let w = name_width.saturating_sub(3);
    let padded = truncate_right(name, w);
    let name_disp = format!("{}", padded.purple().bold());
    let f = &cli.number_format;
    let files_s = match files {
        Some(n) => f.format(n),
        None => String::new(),
    };
    format!(
        " |- {name_disp} {:>8} {:>12} {:>12} {:>12} {:>12}",
        files_s,
        f.format(lines),
        f.format(code),
        f.format(comments),
        f.format(blanks)
    )
}

fn report_row_plain(name: &str, name_width: usize, stats: &CodeStats) -> String {
    let field = name_width + 9;
    let padded = truncate_path_left(name, field);
    format!(
        " {} {:>12} {:>12} {:>12} {:>12}",
        padded,
        stats.lines(),
        stats.code,
        stats.comments,
        stats.blanks
    )
}

fn sorted_language_entries<'a>(
    languages: &'a Languages,
    cli: &Cli,
) -> Vec<(LanguageType, &'a Language)> {
    let mut v: Vec<(LanguageType, &Language)> = languages
        .iter()
        .filter(|(_, l)| !l.is_empty())
        .map(|(k, v)| (*k, v))
        .collect();
    if let Some(sort) = cli.sort {
        v.sort_by(|a, b| {
            let ka = match sort {
                Sort::Files => a.1.files(),
                Sort::Lines => a.1.lines(),
                Sort::Blanks => a.1.blanks,
                Sort::Code => a.1.code,
                Sort::Comments => a.1.comments,
            };
            let kb = match sort {
                Sort::Files => b.1.files(),
                Sort::Lines => b.1.lines(),
                Sort::Blanks => b.1.blanks,
                Sort::Code => b.1.code,
                Sort::Comments => b.1.comments,
            };
            kb.cmp(&ka)
        });
        if cli.sort_reverse {
            v.reverse();
        }
    }
    v
}

pub fn print_table(languages: &Languages, cli: &Cli) -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());

    let any_inaccurate = languages.values().any(|l| l.inaccurate);
    if any_inaccurate {
        writeln!(out, "Note: results can be inaccurate for languages marked with '(!)'")?;
    }

    let total_width = if let Some(c) = cli.columns {
        std::cmp::max(c, 81)
    } else if cli.files {
        terminal_width().map(|t| std::cmp::max(t, 81)).unwrap_or(81)
    } else {
        81
    };
    let name_width = total_width - 63;
    let heavy = "━".repeat(total_width);
    let light_dim = format!("{}", "─".repeat(total_width).dimmed());

    writeln!(out, "{heavy}")?;
    // Header
    {
        let lang_seg = format!("{:<width$}", "Language", width = name_width - 6)
            .blue()
            .bold()
            .to_string();
        let files_seg = format!("{:>14}", "Files").blue().bold().to_string();
        let lines_seg = format!("{:>12}", "Lines").blue().bold().to_string();
        let code_seg = format!("{:>12}", "Code").blue().bold().to_string();
        let com_seg = format!("{:>12}", "Comments").blue().bold().to_string();
        let blank_seg = format!("{:>12}", "Blanks").blue().bold().to_string();
        writeln!(out, " {lang_seg} {files_seg} {lines_seg} {code_seg} {com_seg} {blank_seg}")?;
    }
    writeln!(out, "{heavy}")?;

    let entries = sorted_language_entries(languages, cli);
    let total_lang = build_total(languages);

    for (idx, (lang_type, lang)) in entries.iter().enumerate() {
        let is_last = idx + 1 == entries.len();
        // Summary row for this language.
        writeln!(
            out,
            "{}",
            summary_row(
                lang_type.name(),
                name_width,
                Some(lang.files()),
                lang.lines(),
                lang.code,
                lang.comments,
                lang.blanks,
                cli,
                lang.inaccurate,
                true,
                false,
            )
        )?;

        let show_children = !cli.compact && !lang.children.is_empty();
        if show_children {
            for (child_type, reports) in &lang.children {
                let child = Language::summarise(reports);
                let (clines, ccode, ccomments, cblanks) = child.total();
                writeln!(
                    out,
                    "{}",
                    child_row(
                        child_type.name(),
                        name_width,
                        Some(reports.len()),
                        clines,
                        ccode,
                        ccomments,
                        cblanks,
                        cli,
                    )
                )?;
            }
            let (tlines, tcode, tcomments, tblanks) = lang.total();
            writeln!(
                out,
                "{}",
                summary_row(
                    "(Total)",
                    name_width,
                    None,
                    tlines,
                    tcode,
                    tcomments,
                    tblanks,
                    cli,
                    false,
                    false,
                    false,
                )
            )?;
        }

        if cli.files {
            writeln!(out, "{light_dim}")?;
            let mut reports: Vec<&Report> = lang.reports.iter().collect();
            reports.sort_by(|a, b| a.name.cmp(&b.name));
            for report in reports {
                if cli.compact || report.stats.blobs.is_empty() {
                    writeln!(out, "{}", report_row_plain(&report.name.display().to_string(), name_width, &report.stats))?;
                } else {
                    writeln!(out, " {}", report.name.display())?;
                    // Parent-language line (plain report format).
                    let parent_name = format!("|- {}", lang_type.name());
                    // report_row_plain expects the name without leading
                    // space; construct manually to match " |- X" layout:
                    {
                        let field = name_width + 9;
                        let padded = truncate_path_left(&parent_name, field);
                        writeln!(
                            out,
                            " {} {:>12} {:>12} {:>12} {:>12}",
                            padded,
                            report.stats.lines(),
                            report.stats.code,
                            report.stats.comments,
                            report.stats.blanks
                        )?;
                    }
                    for (blob_lang, blob_stats) in &report.stats.blobs {
                        writeln!(
                            out,
                            "{}",
                            child_row(
                                blob_lang.name(),
                                name_width,
                                None,
                                blob_stats.lines(),
                                blob_stats.code,
                                blob_stats.comments,
                                blob_stats.blanks,
                                cli,
                            )
                        )?;
                    }
                    // Final line for this report, summary format without
                    // truncating the path.
                    writeln!(
                        out,
                        "{}",
                        summary_row(
                            &report.name.display().to_string(),
                            name_width,
                            None,
                            report.stats.lines(),
                            report.stats.code,
                            report.stats.comments,
                            report.stats.blanks,
                            cli,
                            false,
                            false,
                            false,
                        )
                    )?;
                }
            }
            if !is_last {
                writeln!(out, "{light_dim}")?;
            }
        } else if show_children && !is_last {
            writeln!(out, "{light_dim}")?;
        }
    }

    writeln!(out, "{heavy}")?;
    let total_files: usize = languages.values().map(|l| l.files()).sum();
    writeln!(
        out,
        "{}",
        summary_row(
            "Total",
            name_width,
            Some(total_files),
            total_lang.lines(),
            total_lang.code,
            total_lang.comments,
            total_lang.blanks,
            cli,
            total_lang.inaccurate,
            true,
            true,
        )
    )?;
    writeln!(out, "{heavy}")?;
    out.flush()
}

// ---------- print languages (-l) ----------

fn truncate_cell(content: &str, width: usize) -> String {
    let count = content.chars().count();
    if count <= width {
        return content.to_string();
    }
    if width >= 3 {
        let mut s: String = content.chars().take(width - 3).collect();
        s.push_str("...");
        s
    } else if width == 2 {
        let mut s: String = content.chars().take(1).collect();
        s.push('.');
        s
    } else if width == 1 {
        ".".to_string()
    } else {
        String::new()
    }
}

fn pad_cell(content: &str, width: usize) -> String {
    let truncated = truncate_cell(content, width);
    let c = truncated.chars().count();
    let mut out = truncated;
    if c < width {
        out.push_str(&" ".repeat(width - c));
    }
    out
}

pub fn print_languages() -> io::Result<()> {
    let stdout = io::stdout();
    let mut out = io::BufWriter::new(stdout.lock());
    let term = terminal_width();
    let (cell1, cell2) = match term {
        Some(t) if t > 0 => {
            if t <= 88 {
                let cell = t.saturating_sub(4) / 2;
                (cell, cell)
            } else {
                (42, t - 46)
            }
        }
        _ => (35, 35),
    };
    let total = cell1 + cell2 + 2;
    let border = "┃".bold().to_string();
    let make_cell1 = |content: &str| -> String { format!(" {} ", pad_cell(content, cell1 - 2)) };
    let make_cell2 = |content: &str| -> String { format!("    {} ", pad_cell(content, cell2 - 5)) };

    writeln!(out, "{}", "━".repeat(total).bold())?;
    writeln!(
        out,
        "{}{}{}{}",
        border,
        make_cell1("Language").bold(),
        make_cell2("Extensions").bold(),
        border
    )?;
    writeln!(
        out,
        "{}{}{}{}",
        border,
        "━".repeat(cell1).bold(),
        "━".repeat(cell2).bold(),
        border
    )?;
    for lang in LanguageType::all() {
        let spec = lang.spec();
        let exts = if spec.extensions.is_empty() {
            "<None>".to_string()
        } else {
            spec.extensions.join(", ")
        };
        writeln!(out, "{}{}{}{}", border, make_cell1(spec.name), make_cell2(&exts), border)?;
    }
    writeln!(out, "{}", "━".repeat(total).bold())?;
    writeln!(out)?;
    out.flush()
}
EOF"}

