mod cli;
mod fs_walk;
mod input;
mod jupyter;
mod language;
mod output;
mod stats;
mod syntax;

use cli::{build_command, Cli, OutputFormat, Streaming};
use std::io::Write;
use std::path::PathBuf;
use std::process::ExitCode;

fn main() -> ExitCode {
    let matches = build_command().get_matches();
    let verbose = matches.get_count("verbose");
    let level = match verbose {
        1 => log::LevelFilter::Warn,
        2 => log::LevelFilter::Debug,
        3 => log::LevelFilter::Trace,
        _ => log::LevelFilter::Error,
    };
    let _ = env_logger::Builder::new()
        .filter_level(level)
        .write_style(env_logger::WriteStyle::Never)
        .try_init();

    let config = Cli::from_matches(matches);
    log::debug!(target: "tokei::cli", "CLI Config: {:#?}", config);

    if config.print_languages {
        if let Err(e) = output::print_languages() {
            eprintln!("Error: {e:?}");
            return ExitCode::from(1);
        }
        return ExitCode::SUCCESS;
    }

    if let Some(file_input) = config.file_input() {
        let arg = file_input.clone();
        if input::parse_input_file(&arg).is_err() {
            eprint!("{}", input::input_error(&arg));
            return ExitCode::from(1);
        }
    }

    let input_strings = config.inputs();
    // Check existence in order, reporting the first missing path.
    for s in &input_strings {
        if !PathBuf::from(s).exists() {
            eprintln!("Error: '{s}' not found.");
            return ExitCode::from(1);
        }
    }
    let inputs: Vec<PathBuf> = input_strings.iter().map(PathBuf::from).collect();

    if let Some(streaming) = config.streaming {
        if streaming == Streaming::Simple {
            println!("# language                                        path                                          lines         code       comments      blanks   ");
            println!("########## ################################################################################ ############ ############ ############ ############");
            let _ = std::io::stdout().flush();
        }
        let _ = fs_walk::get_statistics(&inputs, &config, Some(streaming));
        return ExitCode::SUCCESS;
    }

    let languages = fs_walk::get_statistics(&inputs, &config, None);

    if let Some(OutputFormat::Json) = config.output {
        output::print_json(&languages);
        return ExitCode::SUCCESS;
    }

    if let Err(e) = output::print_table(&languages, &config) {
        eprintln!("Error: {e:?}");
        return ExitCode::from(1);
    }
    ExitCode::SUCCESS
}
EOF
