cat > vendor/terminal_size/src/lib.rs <<'EOF'
//! A tiny implementation of the `terminal_size` API surface used by
//! clap_builder's `wrap_help` feature. This lets the project be built
//! completely offline from a fresh checkout.

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Width(pub u16);
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Height(pub u16);

#[cfg(unix)]
pub fn terminal_size() -> Option<(Width, Height)> {
    // stdout, then stderr, then stdin.
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        let mut winsz: libc::winsize = unsafe { std::mem::zeroed() };
        let ret = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsz) };
        if ret == 0 && (winsz.ws_col > 0 || winsz.ws_row > 0) {
            return Some((Width(winsz.ws_col), Height(winsz.ws_row)));
        }
    }
    None
}

#[cfg(not(unix))]
pub fn terminal_size() -> Option<(Width, Height)> {
    None
}
