{"command":"cat > src/jupyter.rs <<'EOF'
use crate::language::LanguageType;
use crate::stats::CodeStats;
use crate::syntax::count_language;
use serde_json::Value;

pub fn parse_jupyter(text: &str) -> CodeStats {
    let mut stats = CodeStats::new();
    let Ok(nb) = serde_json::from_str::<Value>(text) else {
        return stats;
    };
    let Some(metadata) = nb.get("metadata") else {
        return stats;
    };
    // Both keys must be present (with values of any type).
    if metadata.get("kernelspec").is_none() || metadata.get("language_info").is_none() {
        return stats;
    }
    let Some(cells) = nb.get("cells").and_then(|c| c.as_array()) else {
        return stats;
    };
    let notebook_lang = metadata
        .pointer("/kernelspec/language")
        .and_then(|v| v.as_str())
        .and_then(LanguageType::from_name_insensitive)
        .unwrap_or(LanguageType::Python);

    // Validate all cells first: an unsupported cell makes the whole
    // notebook count as zero.
    let mut parsed: Vec<(LanguageType, String)> = Vec::new();
    for cell in cells {
        let Some(cell_type) = cell.get("cell_type").and_then(|v| v.as_str()) else {
            return CodeStats::new();
        };
        let lang = match cell_type {
            "code" => notebook_lang,
            "markdown" => LanguageType::Markdown,
            _ => return CodeStats::new(),
        };
        let Some(source_items) = cell.get("source").and_then(|v| v.as_array()) else {
            return CodeStats::new();
        };
        let mut source = String::new();
        for item in source_items {
            let Some(s) = item.as_str() else {
                return CodeStats::new();
            };
            source.push_str(s);
        }
        parsed.push((lang, source));
    }

    for (lang, source) in parsed {
        let cell_stats = count_language(lang, &source);
        stats.blanks += cell_stats.blanks;
        stats.code += cell_stats.code;
        stats.comments += cell_stats.comments;
        stats.add_blob(lang, cell_stats);
    }
    stats
}
EOF
