import subprocess,json,os,shutil,sys,re
# Replay probe_syn1: reconstruct probes list from its script data stored in /tmp/probe_syn1.json (line/block candidates)
D=json.load(open('/tmp/probe_syn1.json'))
langs=json.load(open('/tmp/langs_parsed.json'))
line_candidates=D['line_candidates']; block_candidates=D['block_candidates']
probes=[]
for t in line_candidates: probes.append(f"{t} comment\nhello\n")
for a,b in block_candidates:
    probes.append(f"{a}\nhello\n{b}\nafter\n" if b else f"{a}\nhello\n")
probes.append("hello\nworld\n"); probes.append("")
special={"Meson":"meson.build","NuGet Config":"nuget.config","Pacman's makepkg":"PKGBUILD","Scons":"SConstruct"}
start=int(sys.argv[1]); count=int(sys.argv[2]); exe=sys.argv[3] if len(sys.argv)>3 else "/tmp/ours/executable"
fails=0; total=0
for name,exts in langs[start:start+count]:
    expected=D['results'].get(name)
    if not expected: continue
    issp=name in special
    if exts=="<None>" and not issp: continue
    ext=exts.split(',')[0].strip() if exts!='<None>' else None
    d='/tmp/treplay'; shutil.rmtree(d,ignore_errors=True); os.makedirs(d)
    for pi,content in enumerate(probes):
        if issp:
            sub=os.path.join(d,f"p{pi:03d}"); os.makedirs(sub); p=os.path.join(sub,special[name])
        else: p=os.path.join(d,f"p{pi:03d}.{ext}")
        open(p,'w',encoding='utf8').write(content)
    r=subprocess.run([exe,'-o','json',d],capture_output=True,text=True,timeout=20)
    try: jd=json.loads(r.stdout)
    except: print('ERR',name,r.stdout[:200],r.stderr[:200]); continue
    by={}
    for lang,data in jd.items():
      if lang=='Total': continue
      for rep in data['reports']:
        pi=int(re.search(r'p(\d+)',rep['name']).group(1)); by[pi]=(lang,rep['stats'])
    for pi,row in enumerate(expected['rows']):
        total+=1
        kind,tok,code,com,blank,blobs=row
        got=by.get(pi)
        if code is None:
            ok=got is None
            ours=None
        else:
            ours=(got[1]['code'],got[1]['comments'],got[1]['blanks'],sorted(got[1]['blobs'].keys())) if got else None
            exp=(code,com,blank,sorted(blobs))
            ok=(ours==exp)
            # Also detected language name must match expected? expected detected stored separate; first detected language for detected files should be same lang as in probe (by) - rows don't store lang name, compare got language in expected['detected'] if got
            if got and expected['detected'] and got[0] not in expected['detected']: ok=False
        if not ok:
            fails+=1
            if fails<=80: print('FAIL',name,kind,tok,'expected', (code,com,blank,blobs), 'got', got)
print(f'chunk {start} total {total} fails {fails}')
