            for t in spec.line_comments {
                if t.len() > line_len && self.starts_with(t) {
                    line_len = t.len();
                    line_tok = Some(t);
                }
            }
            let mut block_tok: Option<&'static BlockComment> = None;
            let mut block_len = 0usize;
            for bc in spec.block_comments {
                if bc.start.len() > block_len && self.starts_with(bc.start) {
                    block_len = bc.start.len();
                    block_tok = Some(bc);
                }
            }
            let mut quote_tok: Option<&'static Quote> = None;
            let mut quote_len = 0usize;
            let mut escaped: Option<bool> = None;
            for q in spec.quotes {
                if q.start.len() <= quote_len || !self.starts_with(q.start) {
                    continue;
                }
                let is_escaped = *escaped.get_or_insert_with(|| {
                    let mut count = 0usize;
                    let mut i = self.pos;
                    while i > 0 && self.bytes[i - 1] == b'\\\\' {
                        count += 1;
                        i -= 1;
                    }
