            if block_len != best_len {
                block_tok = None;
            }
            if quote_len != best_len || block_tok.is_some() {
                quote_tok = None;
            }
            if line_len != best_len || block_tok.is_some() || quote_tok.is_some() {
                line_tok = None;
            }

